    var front=my.filter(function(t){return hexNbV(t.id,mRows,mCols).some(function(n){return ni[n]&&(tOwner>=0?ni[n].owner===tOwner:(ni[n].owner!==p&&ni[n].owner!==null&&!ni[n].isDesert));});});
