  function aiLeader(ni,np,excl){var b=-1,bs=-1;for(var qi=0;qi<np.length;qi++){if(qi===excl)continue;var sc=ni.filter(function(t){return t.owner===qi;}).reduce(function(s,t){return s+t.size;},0);if(sc>bs){bs=sc;b=qi;}}return b;}

